INSERT INTO parts(id,sku,name,description,metadata) VALUES ('fdfc2818-9656-46e6-994f-907d5033b762'::uuid,'RF-16D92314','Mini-Circuits BLP-15+','A 50Ω connectorized low-pass filter designed for rugged, high-reliability applications, featuring a passband from DC to 15 MHz and a fast roll-off to 17 MHz','{"image_urls": ["https://mm.digikey.com/Volume0/opasdata/d220001/derivates/1/002/164/878/MFG_BBP-10.7%2B_sml%28200x200%29.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
