INSERT INTO parts(id,sku,name,description,metadata) VALUES ('a6765e1c-436c-40f2-afd2-4d25d86b4f81'::uuid,'RF-326FADA2','Mini-Circuits BLP-150+','A 50 ruggedized, connectorized low-pass filter with a passband from DC to 140 MHz and a 3 dB cutoff at 155 MHz.','{"image_urls": ["https://mm.digikey.com/Volume0/opasdata/d220001/medias/images/6637/BLP-150%2B.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('7554fc55-014f-45fe-9a49-f0a1b6af097b'::uuid,'RF-637F0F16','Mini-Circuits BLP-100+','A 50 lumped element low-pass filter with a DC to 98 MHz passband and a rugged shielded connectorized package (BNC).','{"image_urls": ["https://mm.digikey.com/Volume0/opasdata/d220001/medias/images/6637/BLP-150%2B.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('d29ce3be-3fea-42a7-8fb5-82501e6aec7b'::uuid,'RF-1BC6D85E','Mini-Circuits BLP-50+','A 50 coaxial low-pass filter with a DC to 48 MHz passband, offering high rejection and rugged construction in an FF55 case','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF55.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('22454565-f505-4080-8ed1-5758e4663ffc'::uuid,'RF-75F84EF1','Mini-Circuits BLP-70+','A connectorized low-pass filter with a 50 impedance, featuring a passband from DC to 60 MHz.','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF55.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('ca02701c-6524-4349-8e2a-163af17c019d'::uuid,'RF-B9D9933A','Mini-Circuits BLP-1.9+','A connectorized 50lumped LC low-pass filter with a DC to 1.9 MHz passband and 3 dB cutoff at ~2.5 MHz','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF55.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('389ec9b1-1490-469e-9aa3-a0bb4afe94f2'::uuid,'RF-42C237CF','Mini-Circuits VLF-7200+','A ruggedized SMA-connectorized low-pass filter with a 50 impedance, passing signals from DC to 7200 MHz with low insertion loss and high stopband rejection.','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF704.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('5cac6ad5-3f78-4519-a90d-77636de4672e'::uuid,'RF-921B4ABB','Mini-Circuits VHF-7150+','A high-pass filter with a 7900 to 11000 MHz passband, designed for applications like sub-harmonic rejection, transmitters, receivers, and lab use','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF704.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('ed929379-62cc-49b4-a5d9-d137567a06cd'::uuid,'RF-C99E5958','Mini-Circuits Frequency Mixer(ZX05-153MH-S+)','A high-performance Level 13 double-balanced mixer designed for wideband operation from 3.2 to 15 GHz, with an IF bandwidth from DC to 4 GHz','{"image_urls": ["https://www.minicircuits.com/images/case_style/FL905.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('2d167327-9aa4-4890-932a-47edd73471dd'::uuid,'RF-4D8585F5','KRYTAR 3DB 180(DEG)HYBRID 4060200(6-20 GHZ)','high-performance 4-port components designed for ultra-broadband signal splitting and combining','{"image_urls": ["https://krytar.com/wp-content/uploads/2022/03/krytar.4060200.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('ba8d4a98-6100-4941-8670-546ea69f666e'::uuid,'RF-1EBE3139','K&L 5FV30-5200/T500-O/O','This is a precision bandpass filter featuring a 5200 MHz center frequency and a 500 MHz passband (4950–5450 MHz). Designed for rugged RF environments, it uses SMA Female connectors (O/O) for low-loss signal integration.','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('dc32e9ed-88fe-45ef-8f35-bbde03ebae10'::uuid,'RF-D21D2D23','K&L 5FV30-4600/T500-O/O','This is a high-selectivity cavity filter featuring a 4600 MHz center frequency and a 500 MHz total bandwidth (4350–4850 MHz).','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('554effae-27be-4879-8ea8-3a6fe3660b70'::uuid,'RF-E96EB0E3','K&L 5FV30-4800/T500-O/O','This is a high-performance, 5-section cavity bandpass filter designed for precision frequency control at a center frequency of 4800 MHz. It features a 500 MHz bandwidth (4550–5050 MHz), delivering high out-of-band rejection and steep roll-off through its combline architecture.','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('d4e45569-3890-40bb-9b64-12cacb615407'::uuid,'RF-AFC2B6DA','K&L 5FV30-5400/T500-O/O','This is a high-selectivity 5-section cavity bandpass filter designed for the 5.4 GHz frequency range. It features a center frequency of 5400 MHz with a 500 MHz total bandwidth.Utilizing a combline cavity design, it provides sharp rejection of out-of-band signals and low passband insertion loss.','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('285e97f9-5ec4-4d79-bfa9-8a2bef056b7d'::uuid,'RF-49C1DA9A','K&L 5FV30-5500/T500-O/O','This is a precision-engineered 5-section cavity bandpass filter centered at 5500 MHz. It provides a wide 500 MHz bandwidth (5250–5750 MHz), offering superior out-of-band rejection and low insertion loss via its high-Q combline architecture.','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('15610eb6-b94d-407e-b3f3-32bbcbf05a01'::uuid,'RF-17EFBE7B','K&L 5FV30-5600/T500-O/O','This is a high-selectivity 5-section cavity bandpass filter designed for precision signal filtering at a 5600 MHz center frequency. With a 500 MHz total bandwidth (5350–5850 MHz), it utilizes a combline cavity architecture to provide steep out-of-band rejection and low insertion loss','{"image_urls": ["https://www.fairviewmicrowave.com/content/dam/infinite-electronics/product-assets/fairview-microwave/images/SF2402-SMA.jpg"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('873fb584-db26-4e84-8fe0-8fd527e572da'::uuid,'RF-8321CE3C','K&L 6L250-8000/T18000-O/O','This is a precision tubular lowpass filter featuring an 8000 MHz (8.0 GHz) 3 dB cutoff frequency. Part of the 6L250 series, this 6-section filter offers a steep rejection profile with a 50 dB stopband extending from 10,880 to 18,000 MHz.','{"image_urls": ["https://surplussales-prod-media.sfo3.digitaloceanspaces.com/sfo3/CACHE/images/item_images/rf/filters/fbp-5b120-160-21-op-o_lg/8f106b65da36de67eb2ca5aa0c6b0ffe.webp"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('3e0a7686-b74f-4e86-9baa-4443c39f366b'::uuid,'RF-4970B9E8','Mini-Circuits VLF 5500-S+','The Mini-Circuits VLF-5500-S+ is a high-performance coaxial low pass filter designed for high-frequency applications from DC to 5500 MHz. It features a sharp 6.2 GHz cutoff frequency and a 7-section design that ensures excellent out-of-band rejection (typically >20 dB at 7.2 GHz).','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF704.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
INSERT INTO parts(id,sku,name,description,metadata) VALUES ('80b48834-5849-4e72-9c52-75871a80fe31'::uuid,'RF-4604AE41','Mini-Circuits VLF 6400+','7-Section Coaxial Low Pass Filter (6.4 GHz),The Mini-Circuits VLF-6400+ is a precision low pass filter designed for operation from DC to 6400 MHz. Built with a patented, rugged uni-body construction, it features a 7-section design that provides a sharp 3dB cutoff at 7150 MHz and deep out-of-band rejection (typically >40 dB at 9.6 GHz).','{"image_urls": ["https://www.minicircuits.com/images/case_style/FF704.png"]}'::jsonb) ON CONFLICT (sku) DO NOTHING;
